routes = {}

def route(method, path):
    def register(func):
        routes[(method, path)] = func      # remember the handler, return it unchanged
        return func
    return register

@route("GET", "/health")
def health():
    return 200, {"status": "ok"}

@route("POST", "/echo")
def echo(body):
    return 201, body

def handle(method, path, body=None):
    # Find the handler for (method, path) and return its (status, body).
    # Unknown path: (404, {"detail": "Not Found"}).
    # Known path, other method: (405, {"detail": "Method Not Allowed"}).
    # Pass body to the handler only for POST.
    return 501, {"detail": "Not Implemented"}

requests = [("GET", "/health"), ("POST", "/echo", {"msg": "hi"}), ("GET", "/nope"), ("DELETE", "/health")]
for request in requests:
    print(*handle(*request))

import re

def compile_route(pattern):
    """Turn "/users/{user_id}" into a regex with a named group per {name}."""
    # Replace each {name} with (?P<name>[^/]+) using re.sub.
    return re.compile("^" + pattern + "$")

routes = [
    ("/users/me", "current_user"),
    ("/users/{user_id}", "get_user"),
    ("/users/{user_id}/posts/{post_id}", "get_post"),
]
compiled = [(compile_route(p), name) for p, name in routes]

def resolve(path):
    for regex, name in compiled:          # first match wins, so order matters
        m = regex.match(path)
        if m:
            return name, m.groupdict()
    return None

for path in ["/users/me", "/users/42", "/users/42/posts/7", "/users"]:
    print(path, "->", resolve(path))

