from fastapi import FastAPI, HTTPException, Request, status
from fastapi.responses import JSONResponse

app = FastAPI()
BOOKS = {1: {"title": "Dune"}}

class OutOfStock(Exception):                  # a domain error: knows nothing of HTTP
    def __init__(self, item: str):
        self.item = item

@app.exception_handler(OutOfStock)            # one place maps it to an HTTP response
async def out_of_stock(request: Request, exc: OutOfStock):
    return JSONResponse(status_code=409, content={"detail": f"{exc.item} is out of stock"})

@app.delete("/books/{book_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_book(book_id: int) -> None:
    if BOOKS.pop(book_id, None) is None:
        raise HTTPException(status_code=404, detail="Book not found")

@app.post("/orders", status_code=201)
def create_order(item: str):
    if item == "dune":
        raise OutOfStock(item)                # business code raises domain errors
    return {"item": item}

# DELETE /books/1        -> 204, empty body
# DELETE /books/1 again  -> 404 {"detail": "Book not found"}
# POST /orders?item=dune -> 409 {"detail": "dune is out of stock"}
# POST /orders?item=pen  -> 201 {"item": "pen"}

from typing import Annotated

from fastapi import Depends, FastAPI, Header, HTTPException

app = FastAPI()

class Database:                              # stands in for a SQLAlchemy Session
    def __init__(self):
        self.open = True
    def close(self):
        self.open = False

def get_db():
    db = Database()
    try:
        yield db                             # the endpoint runs here
    finally:
        db.close()                           # always runs after the response

def get_current_user(x_api_key: Annotated[str | None, Header()] = None) -> str:
    if x_api_key != "secret-key":            # reads the X-API-Key header
        raise HTTPException(status_code=401, detail="Invalid API key")
    return "ana"

DB = Annotated[Database, Depends(get_db)]    # reusable aliases
CurrentUser = Annotated[str, Depends(get_current_user)]

@app.get("/me")
def me(user: CurrentUser, db: DB):
    return {"user": user, "db_open": db.open}

# GET /me                          -> 401 {"detail": "Invalid API key"}
# GET /me  (X-API-Key: secret-key) -> 200 {"user": "ana", "db_open": true}

