import hashlib
import hmac
import secrets
from typing import Annotated

from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm

app = FastAPI()

def hash_password(password: str, salt: bytes | None = None) -> str:
    salt = salt or secrets.token_bytes(16)                 # unique salt per user
    digest = hashlib.scrypt(password.encode(), salt=salt, n=2**14, r=8, p=1)
    return salt.hex() + ":" + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    salt_hex, digest_hex = stored.split(":")
    candidate = hash_password(password, bytes.fromhex(salt_hex)).split(":")[1]
    return hmac.compare_digest(candidate, digest_hex)     # constant-time comparison

USERS = {"ana": {"hash": hash_password("correct horse"), "role": "admin"},
         "bo": {"hash": hash_password("battery staple"), "role": "member"}}
TOKENS: dict[str, str] = {}               # token -> username; real apps store sessions

oauth2 = OAuth2PasswordBearer(tokenUrl="token")   # reads "Authorization: Bearer ..."

@app.post("/token")                       # form fields username and password
def login(form: Annotated[OAuth2PasswordRequestForm, Depends()]):
    user = USERS.get(form.username)
    if user is None or not verify_password(form.password, user["hash"]):
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "Wrong username or password")
    token = secrets.token_urlsafe(32)
    TOKENS[token] = form.username
    return {"access_token": token, "token_type": "bearer"}

def current_user(token: Annotated[str, Depends(oauth2)]) -> str:
    if token not in TOKENS:
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "Invalid token",
                            headers={"WWW-Authenticate": "Bearer"})
    return TOKENS[token]

@app.delete("/books/{book_id}", status_code=204)
def delete_book(book_id: int, user: Annotated[str, Depends(current_user)]):
    if USERS[user]["role"] != "admin":    # authenticated, but not allowed
        raise HTTPException(status.HTTP_403_FORBIDDEN, "Admins only")

