import time

import httpx
from fastapi import BackgroundTasks, FastAPI

app = FastAPI()

@app.get("/report")
def report():                       # plain def: FastAPI runs it in a thread pool
    time.sleep(1)                   # blocking is acceptable: it occupies one pool thread
    return {"ok": True}

@app.get("/weather")
async def weather():                # async def: runs on the event loop itself
    async with httpx.AsyncClient(timeout=5) as client:
        r = await client.get("https://api.example.com/weather")   # yields while waiting
    return r.json()

@app.get("/bad")
async def bad():
    time.sleep(1)                   # blocks the event loop: every request on this worker waits
    return {"ok": True}

def send_welcome_email(email: str) -> None:
    ...                             # slow, and the client does not need to wait for it

@app.post("/signup", status_code=201)
def signup(email: str, background: BackgroundTasks):
    background.add_task(send_welcome_email, email)   # runs after the response is sent
    return {"email": email}

